a = ru8(base + componentKeyByteRva)
b = ru8(base + componentKeySecondByteRva)
lut = ${component_lut}

substitute4(v):
  result = 0
  for i = 0; i < 64; i += 4:
    result |= uint64(lut[(v >> i) & 15]) << i
  return result

v = encrypted_component_entry
v += ${comp_add1}
v ^= a
v = ror64(v, ${comp_ror1})
v ^= ${comp_xor1}
v = substitute4(v)
v += ${comp_add2}
v = ror64(v, ${comp_ror2})
v ^= b
v ^= ${comp_xor2}
v = substitute4(v)
v -= ${comp_sub}
v = ror64(v, ${comp_ror3})
v += ${comp_add3}
v ^= ${comp_xor3}
v = ror64(v, ${comp_ror4})
v ^= ${comp_xor4}
component = v

v = ru64(component + ${parent_offset})
v ^= ${parent_xor}
v -= ${parent_sub}
parent = ror64(v, ${parent_ror})

v = ru64(base + Address_viewmatrix_base)
v ^= ${camera_xor}
p1 = ru64(v + ${camera_field_add})
// Remaining camera chain is not independently extracted.

owner = ru64(base + GlobalAdmin_RVA)
v = ru64(owner + ${singleton_owner_offset})
v = ror64(v, ${singleton_ror1})
v += ${singleton_add1}
v = ror64(v, ${singleton_ror2})
v ^= ${singleton_xor}
v += ${singleton_add2}
singleton_table = v

v = ru64(visibility_component + ${visibility_offset})
v = ror64(v, ${vis_ror1})
v ^= ${vis_xor}
v += ${vis_add}
v = ror64(v, ${vis_ror2})
visible = v == ${vis_true}

parent = ror64((ru64(link + ${map_parent_offset}) ^ ${map_parent_xor}) - ${map_parent_sub}, ${map_parent_ror})
owner = ((ru64(parent + ${map_owner_offset}) - ${map_owner_sub}) ^ ${map_owner_xor}) + ${map_owner_add2}
buckets = ror64(((ru64(owner + ${map_buckets_offset}) - ${map_buckets_sub1}) ^ ${map_buckets_xor}) - ${map_buckets_sub2}, ${map_buckets_ror})
// uint64 arithmetic; all reads must be complete. Check decoded pointers, not encoded values.
uid_offset = one_of(${map_uid_d0}, ${map_uid_d4}, ${map_uid_d8})
uid = ru32(link + uid_offset)
bucket = buckets + (uid & ${map_uid_mask}) * 16 // fixed ADD/SIB structure proves bucket stride
entries = ru64(bucket)
count = ru32(bucket + ${map_bucket_count})
for i in [0, count):
  entry = entries + i * ${map_entry_stride}
  if ru32(entry) == uid: body = ru64(entry + ${map_entry_body})
// Keep full UID comparison, unique match, bounded count and before/after identity checks.
// Native guard synchronization is not reproduced by external reads.

owner = ru64(base + ${map_data_admin})
v = ru64(owner + ${map_data_table_offset})
v = ror64(v, ${map_data_rotate_0})
v += ${map_data_constant_0}
v = ror64(v, ${map_data_rotate_1})
v ^= ${map_data_constant_1}
v += ${map_data_constant_2}
map_record = ru64(v + ${map_data_slot} * 8)
map_id = ru64(map_record + ${map_data_id_offset})
// Re-read owner/table/record/id before accepting a snapshot.

entries = ru64(alpha_view + ${outline_alpha_view_array})
count = ri32(alpha_view + ${outline_alpha_view_count})
// Fixed LEA/SIB operands establish count * 20.
if count > 0:
  value = rf32(entries + count * 20 + uint64(${outline_alpha_last_delta}) + ${outline_alpha_value})
// alpha_view is the native getter argument (component interior +0x20 in retained evidence).
// Offsets above are relative to that argument; do not apply them directly to the component.
// Legacy per-component alpha is not the active native HUD brightness setting.

All arithmetic below is uint64 modulo 2^64; this is a read-only reference.
admin = read64(base + ${native_outline_root});
raw = read64(admin + ${native_outline_encoded_offset});
table = (ror64(ror64(raw, ${native_outline_ror1}) + ${native_outline_add1}, ${native_outline_ror2}) ^ ${native_outline_xor}) + ${native_outline_add2};
profile = read64(table + ${native_outline_selector} * 8);
descriptor = profile + ${native_outline_descriptor_offset};
entries = read64(descriptor + ${native_outline_entries_offset});
count = read_i32(descriptor + ${native_outline_count_offset});
Require complete reads, valid pointers and a bounded nonnegative count.
Find exactly one entry = entries + i * ${native_outline_entry_stride}
where read64(entry + ${native_outline_entry_key_offset}) == ${native_outline_setting_key}.
brightness = read_float32(entry + ${native_outline_entry_value_offset});
Recheck the chain and entry identity after reading; no match is unknown, not zero.
A match does not authorize writes or establish visual brightness behavior.

